style.css:
@-moz-document domain("roblox.com"), domain("create.roblox.com") {
/* Universal reset */
  * {
    font-family: Arial, sans-serif !important;
    border-radius: 0 !important;
    transition: none !important;
    animation: none !important;
  }

  html, body {
    background-color: #f2f2f2 !important;
    color: #111 !important;
  }

  /* Navbar */
  .rbx-header, .navigation-bar, .navbar, .nav-container {
    background-color: #e3e3e3 !important;
    border-bottom: 1px solid #c4c4c4 !important;
    box-shadow: none !important;
  }

  /* Old Roblox Logo */
  .navbar-brand-logo img,
  .navigation-logo img,
  [class*="logo"] img {
    content: url("https://vignette.wikia.nocookie.net/roblox/images/6/6b/Roblox_2015_logo.png") !important;
    height: 45px !important;
  }

  /* Buttons */
  button, .btn-primary, .btn-secondary, .btn-control-md, .btn-growth-sm, .btn-common-play-game-lg {
    background-color: #d6d6d6 !important;
    color: #000 !important;
    border: 1px solid #a0a0a0 !important;
    box-shadow: none !important;
  }

  button:hover, .btn-primary:hover {
    background-color: #bdbdbd !important;
  }

  /* Game thumbnails and avatars */
  .game-card-thumb-container img,
  .game-icon img,
  .thumbnail-2d-container img,
  img[src*="game"],
  img[src*="asset-thumbnail"],
  .avatar-card-image,
  .avatar-headshot-lg,
  .avatar-image,
  .avatar-card-container img {
    border-radius: 0 !important;
    box-shadow: none !important;
  }

  /* Containers and cards */
  .profile-header, .profile-header-content,
  .section-content, .container-header,
  .game-card-container, .card-item,
  .standard-page, .container, .charts-container,
  .premium-container, .membership-container,
  .robux-container, .purchase-section,
  .create-page, .studio-content {
    background-color: #ffffff !important;
    border: 1px solid #cccccc !important;
    color: #000 !important;
  }

  /* Text styling */
  h1, h2, h3, h4, .text-label, .label-text, .font-header-2,
  .game-card-name, .game-name, .text-overflow {
    color: #111 !important;
    font-weight: bold !important;
  }

  /* Footer */
  .footer, .site-footer {
    background-color: #e3e3e3 !important;
    color: #000 !important;
  }

  /* Hide modern overlays */
  .dark-theme, .theme-dark,
  .promo-banner, .cookie-banner,
  .ad, .ads-container, .advertisement,
  .chart-banner-container, .chart-filter-bar {
    display: none !important;
  }
}
